  IEnumerator Resolve(){long earned=0;for(int beat=1;beat<=8;beat++){if(!skipRequested)sound.Cue("beat");foreach(var e in result.Events.Where(e=>e.Beat==beat)){earned+=e.Credits;if(e.Credits>0&&!skipRequested){sound.Cue("cash");var n=run.Board.Nodes.Find(z=>z.Id==e.Source);if(n!=null){var t=Studio.Label(root,"+"+e.Credits,38+(n.X+.5f)*644f/run.Board.Width-55,310+(n.Y+.3f)*644f/run.Board.Height,110,70,23,Studio.Accent,TextAlignmentOptions.Center,true);if(!data.Profile.ReducedMotion)t.gameObject.AddComponent<FloatingNumber>();}}if(e.Reason=="shipment"&&!skipRequested)Pulse(e);}score.text=earned.ToString("N0")+" · "+beat+"/8";if(skipRequested)yield return null;else yield return new WaitForSeconds(data.Profile.ReducedMotion?.08f:.42f);}busy=false;sound.Cue(result.Credits>=run.Mission.Target?"win":"loss");Result();}
  void Pulse(FlowEvent e){if(data.Profile.ReducedMotion)return;var a=run.Board.Nodes.Find(n=>n.Id==e.Source);var b=run.Board.Nodes.Find(n=>n.Id==e.Target);if(a==null||b==null)return;var dot=Studio.Box(root,"Flow",38+(a.X+.5f)*644f/run.Board.Width-7.5f,310+(a.Y+.5f)*644f/run.Board.Height-7.5f,15,15,FlatUI.Hex(e.Kind==0?"#62E3BB":e.Kind==1?"#F3BB60":"#78BDE6"));StartCoroutine(Travel(dot,b.X-a.X,b.Y-a.Y));}
  IEnumerator Travel(RectTransform dot,int dx,int dy){var start=dot.anchoredPosition;float time=0;while(time<.28f){time+=Time.deltaTime;dot.anchoredPosition=start+new Vector2(dx*grid.rect.width/run.Board.Width,-dy*grid.rect.height/run.Board.Height)*Mathf.Clamp01(time/.28f);yield return null;}Destroy(dot.gameObject);}
