  void Themes(){Base("themes");Studio.Header(root,"A CITY OF YOUR OWN","District palettes","Complete a district to earn its skyline.",Menu);for(int i=0;i<6;i++){int theme=i;bool open=data.Profile.StyleUnlocked(i);Studio.Image(root,"district"+i,38+(i%2)*330,260+(i/2)*285,314,176);var button=Studio.Button(root,open?(data.Profile.Theme==i?"SELECTED":"USE PALETTE"):Profile.StyleCost(i)+" CR / "+(i*12)+" CLEARS",38+(i%2)*330,448+(i/2)*285,314,96,()=>{if(open)data.Profile.SetTheme(theme);else if(data.Profile.BuyStyle(theme))data.Profile.SetTheme(theme);Save();Themes();});button.interactable=open||data.Profile.Credits>=Profile.StyleCost(i);}}
  void Settings(){Base("settings");Studio.Header(root,"MAKE YOURSELF AT HOME","Settings","Saved on this device. Everything works offline.",Menu);string[] labels={"MUSIC","SOUND EFFECTS","HAPTICS","REDUCED MOTION","HIGH CONTRAST"};bool[] values={data.Profile.Music,data.Profile.Sound,data.Profile.Haptics,data.Profile.ReducedMotion,data.Profile.HighContrast};for(int i=0;i<5;i++){int k=i;Studio.Button(root,labels[i]+"     "+(values[i]?"ON":"OFF"),38,270+i*112,644,92,()=>{if(k==0)data.Profile.Music=!data.Profile.Music;if(k==1)data.Profile.Sound=!data.Profile.Sound;if(k==2)data.Profile.Haptics=!data.Profile.Haptics;if(k==3)data.Profile.ReducedMotion=!data.Profile.ReducedMotion;if(k==4)data.Profile.HighContrast=!data.Profile.HighContrast;sound.Refresh();Save();Settings();});}Studio.Button(root,"HOW TO PLAY",38,867,644,92,Help);Studio.Button(root,"HINT FOR THIS CITY",38,975,644,92,Hint);Studio.Button(root,"SAVE RECOVERY",38,1083,644,92,SaveWarning);}
  void Help(){var m=Studio.Modal(root,"MAKE THE CONNECTION",Settings);Studio.Label(m,"1  Move a home beside a shop. Mint arrows send resources into gold input dots.\n\n2  Every shop needs people and goods. Farms need one starting energy, already supplied.\n\n3  CHECK forecasts eight beats for free. RUN animates the real result.\n\n4  The + tray adds buildings using this city’s budget. Returning a building refunds its build cost.\n\n5  Earn one star to progress. Replay to improve your chain.\n\nDrag or select then tap. R rotates. Z undoes. Space runs. Escape opens the desk.",44,240,632,790,29);Studio.Button(m,"LET'S BUILD",44,1090,632,135,Board,true);}
  void Hint(){Board();var n=run.Hint();if(n==null){message="All buildings match the reference network. Run your city!";Board();return;}var target=run.Mission.Solution.Nodes.First(z=>z.Id==n.Id);message=Pieces.Get(n.Kind).Label+": try column "+(target.X+1)+", row "+(target.Y+1)+", facing "+new[]{"east","south","west","north"}[target.Rotation]+".";Board();}
  void SaveWarning(){var m=Studio.Modal(root,"YOUR LOCAL SAVE",Menu);Studio.Label(m,canSave?"Progress is saved after every move and result. A validated backup is kept automatically.\n\nPrototype saves are preserved separately.\n\n"+message:"The existing save could not be validated. It has been preserved. Close the game and keep the save files for recovery. No new progress will overwrite them.\n\n"+message,44,250,632,560,30);Studio.Button(m,"NEW LOCAL GAME",44,930,632,125,ConfirmReset);Studio.Button(m,"BACK",44,1090,632,135,Menu,true);}
  void ConfirmReset(){var m=Studio.Modal(root,"START A NEW LOCAL GAME?",Menu);Studio.Label(m,"This starts the campaign and collection over on this device.\n\nExisting save files are archived beside the original save, not deleted.\n\nPreviously purchased nonconsumables can only be restored through the real platform store. No purchases are simulated here.",44,265,632,600,31);Studio.Button(m,"KEEP MY CURRENT GAME",44,940,632,130,Menu,true);Studio.Button(m,"ARCHIVE & START OVER",44,1090,632,130,()=>{try{canSave=false;disk.ArchiveForReset();UnityEngine.SceneManagement.SceneManager.LoadScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene().name);}catch(Exception){message="Could not archive the save. Existing files were preserved.";Menu();}});}
  void About(){var m=Studio.Modal(root,"A SMALL, OFFLINE CITY",Menu);Studio.Label(m,"CASHFLOW CHAINS\nPlaytest edition 1.0\n\nOriginal 2D artwork and synthesized music. DejaVu fonts under their included license.\n\nNo account, ads, real cash redemption or network gameplay. Credits stay inside the game.\n\nPurchases are unavailable in this local edition. No store prices or transactions are simulated.\n\nYour progress lives only on this device. Uninstalling may remove it.",44,230,632,820,28);Studio.Button(m,"COSMETICS & RESTORE",44,1090,632,135,Shop,true);}
  async void Shop(){var m=Studio.Modal(root,"OPTIONAL COSMETICS",Menu);Studio.Label(m,"Neon city cosmetic: a pink accent palette and skyline, also earned through play.\n\nPurchases never change puzzle rules, alert, scores or targets.\n\nPrices appear only when returned by the actual platform store.",44,240,632,500,30);var info=Studio.Label(m,store.Status,44,790,632,150,27,Studio.Muted);var buy=Studio.Button(m,"UNAVAILABLE",44,975,632,115,()=>{store.Buy();info.text=store.Status;},true);buy.interactable=false;Studio.Button(m,"RESTORE PURCHASES",44,1110,632,115,()=>{store.Restore();info.text=store.Status;});await store.Connect();if(info){info.text=store.Status;buy.GetComponentInChildren<TextMeshProUGUI>().text=store.Owned?"OWNED":store.Price??"UNAVAILABLE";buy.interactable=store.Ready&&!store.Owned;}}
  void Probe(){string dir=FlatUI.Arg("-capture-dir");if(dir==null)return;Directory.CreateDirectory(dir);data.Board=run.Board.Copy();File.WriteAllText(Path.Combine(dir,"campaign-state.json"),JsonUtility.ToJson(new ProbeState{Screen=screen,Selected=selected,Save=data},true));}
  [Serializable] sealed class ProbeState{public string Screen;public int Selected;public CitySave Save;}
 }
